// microbit - methods
ACMsg.MICROBIT_RESET = "Redémarre la carte micro:bit de manière logicielle, équivalent à une pression sur le bouton reset.";
ACMsg.MICROBIT_SLEEP = "Met le programme en pause pendant <b>ms</b> millisecondes.";
ACMsg.MICROBIT_RUNNING_TIME = "Retourne le temps écoulé depuis le démarrage de la carte en millisecondes.";
ACMsg.MICROBIT_PANIC = "Affiche un code d'erreur <b>error_code</b> sur la matrice de LEDs et redémarre la carte.";
ACMsg.MICROBIT_TEMPERATURE = "Retourne la température approximative de la carte en degrés Celsius.";
ACMsg.MICROBIT_SET_VOLUME = "Définit le volume sonore global de la carte avec la valeur <b>volume</b> comprise entre 0 et 255.";
ACMsg.MICROBIT_WS2812_WRITE = "Écrit les données du buffer <b>buf</b> sur une bande de LEDs WS2812 connectée à la broche <b>pin</b>. Le buffer doit être de type bytes ou bytearray.";
ACMsg.MICROBIT_RUN_EVERY = "Exécute la fonction <b>func</b> toutes les <b>ms</b> millisecondes en arrière-plan.";
ACMsg.MICROBIT_SCALE = "Convertit la valeur <b>value</b> d'un intervalle défini par <b>from_low</b> et <b>from_high</b> vers un nouvel intervalle défini par <b>to_low</b> et <b>to_high</b>.";
ACMsg.MICROBIT_RUN_EVERY = "Planifie l'exécution d'une fonction à l'intervalle spécifié par les arguments de temps. Chaque argument correspond à une unité de temps différente et elles s'additionnent. Ainsi, <b>run_every(min=1, s=30)</b> planifie le rappel toutes les minutes et demie. Lorsqu'une exception est levée dans la fonction de rappel, celle-ci est annulée. Pour éviter cela, vous pouvez gérer les exceptions avec <b>try/except</b>. <b>run_every</b> peut également être utilisé comme décorateur, placé au-dessus de la fonction à planifier.";
ACMsg.MICROBIT_RUN_EVERY_DECORATOR = "Planifie l'exécution d'une fonction à l'intervalle spécifié par les arguments de temps. Chaque argument correspond à une unité de temps différente et elles s'additionnent. Ainsi, <b>run_every(min=1, s=30)</b> planifie le rappel toutes les minutes et demie. Lorsqu'une exception est levée dans la fonction de rappel, celle-ci est annulée. Pour éviter cela, vous pouvez gérer les exceptions avec <b>try/except</b>. <b>run_every</b> peut également être utilisée comme fonction, en passant comme 1er argument la fonction à planifier.";
// microbit - display
ACMsg.MICROBIT_DISPLAY = "Ce module contrôle l'afficheur LED 5x5 situé en façade de votre carte. Il permet d'afficher des images, des animations et même du texte.";
ACMsg.MICROBIT_DISPLAY_GET_PIXEL = "Renvoie la luminosité de la LED à la colonne <b>x</b> et à la ligne <b>y</b> sous forme d'un entier compris entre <b>0</b> (éteinte) et <b>9</b> (lumineuse).";
ACMsg.MICROBIT_DISPLAY_SET_PIXEL = "Réglez la luminosité de la LED à la colonne <b>x</b> et à la ligne <b>y</b> sur <b>value</b>, qui doit être un entier compris entre <b>0</b> et <b>9</b>.";
ACMsg.MICROBIT_DISPLAY_CLEAR = "Éteint toutes les LED de l'écran en mettant leur luminosité à <b>0</b>.";
ACMsg.MICROBIT_DISPLAY_SHOW = "Affiche une <b>image</b> sur l'écran.";
ACMsg.MICROBIT_DISPLAY_SHOW_ADVANCED = "Si <b>image</b> est une chaîne de caractères, un nombre entier ou décimal, les lettres ou chiffres sont affichés les uns après les autres. Si <b>image</b> est une séquence d'images, celles-ci sont affichées successivement. Chaque lettre, chiffre ou image est affiché pendant <b>delay</b> millisecondes. Si <b>wait</b> vaut <b>True</b>, la fonction attend la fin de l'animation, sinon l'animation se déroule en arrière-plan. Si <b>loop</b> vaut <b>True</b>, l'animation se répète indéfiniment. Si <b>clear</b> vaut <b>True</b>, l'écran est effacé à la fin de l'animation. Les paramètres <b>wait</b>, <b>loop</b> et <b>clear</b> doivent être fournis comme arguments nommés.";
ACMsg.MICROBIT_DISPLAY_SCROLL = "Fait défiler un <b>text</b> horizontalement sur l'écran. Si <b>text</b> est un nombre entier ou décimal, il est d'abord converti en texte. Le paramètre <b>delay</b> contrôle la vitesse de défilement. Si <b>wait</b> vaut <b>True</b>, la fonction attend la fin de l'animation, sinon elle s'exécute en arrière-plan. Si <b>loop</b> vaut <b>True</b>, le défilement se répète indéfiniment. Si <b>monospace</b> vaut <b>True</b>, chaque caractère occupe <b>5</b> colonnes de pixels, sinon un seul pixel vide sépare les caractères. Les paramètres <b>wait</b>, <b>loop</b> et <b>monospace</b> doivent être fournis comme arguments nommés.";
ACMsg.MICROBIT_DISPLAY_ON = "Allume l'écran avec <b>on()</b>.";
ACMsg.MICROBIT_DISPLAY_OFF = "Éteint l'écran avec <b>off()</b>, ce qui permet de réutiliser les broches GPIO associées à l'afficheur pour d'autres usages.";
ACMsg.MICROBIT_DISPLAY_IS_ON = "Retourne <b>True</b> si l'écran est allumé, sinon retourne <b>False</b>.";
ACMsg.MICROBIT_DISPLAY_READ_LIGHT_LEVEL = "Utilise les LED de l'écran comme capteur de lumière. Retourne un entier compris entre <b>0</b> et <b>255</b> représentant le niveau de luminosité ambiante (plus la valeur est élevée, plus la lumière est forte).";
// microbit - Image
ACMsg.MICROBIT_IMAGE = "La classe <b>Image</b> est utilisée pour créer des images pouvant être facilement affichées sur la matrice LED de l'appareil. À partir d'un objet image, il est possible de l'afficher via l'API <b>display</b>."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_STR = "Si <b>string</b> est utilisé, la chaîne doit être composée de chiffres de 0 à 9 disposés en lignes, décrivant l'image, par exemple :<pre>\n\nimage = Image('09090:'\n\t      '99999:'\n\t      '99999:'\n\t      '09990:'\n\t      '00900:')\n</pre>créera une image 5x5 d'un X. La fin d'une ligne est indiquée par un deux-points."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_BUF = "Cette méthode crée une image vide avec <b>width</b> collonnes et <b>height</b> lignes. Le paramètre <b>buffer</b> peut être un tableau de taille <b>width</b> * <b>height</b> contenant des entiers de 0 à 0. Par exemple:<pre>\n\nImage(2, 2, b'\\x08\\x08\\x08\\x08')\nou\nImage(2, 2, bytearray([9,9,9,9]))\n\n</pre> créera une image 2x2 de luminosité 9."
ACMsg.MICROBIT_IMAGE_BUILTIN_SEQ = "Séquence d'images intégrée (animation), par exemple <b>Image.ALL_CLOCKS</b> ou <b>Image.ALL_ARROWS</b>.";
ACMsg.MICROBIT_IMAGE_HEIGHT = "Renvoie la hauteur de l'image (nombre de lignes).";
ACMsg.MICROBIT_IMAGE_WIDTH = "Renvoie la largeur de l'image (nombre de colonnes).";
ACMsg.MICROBIT_IMAGE_COPY = "Renvoie une copie de l'image.";
ACMsg.MICROBIT_IMAGE_INVERT = "Renvoie une nouvelle image avec la luminosité des pixels inversée.";
ACMsg.MICROBIT_IMAGE_GET_PIXEL = "Renvoie la luminosité à la colonne <b>x</b> et la ligne <b>y</b> sous forme d'un entier entre <b>0</b> et <b>9</b>.";
ACMsg.MICROBIT_IMAGE_SET_PIXEL = "Règle la luminosité à la colonne <b>x</b> et la ligne <b>y</b> sur <b>value</b> (entier entre <b>0</b> et <b>9</b>).";
ACMsg.MICROBIT_IMAGE_FILL = "Met tous les pixels à <b>value</b> (entier entre <b>0</b> et <b>9</b>).";
ACMsg.MICROBIT_IMAGE_SHIFT_LEFT = "Renvoie une nouvelle image décalée vers la gauche de <b>n</b> colonnes.";
ACMsg.MICROBIT_IMAGE_SHIFT_RIGHT = "Renvoie une nouvelle image décalée vers la droite de <b>n</b> colonnes.";
ACMsg.MICROBIT_IMAGE_SHIFT_UP = "Renvoie une nouvelle image décalée vers le haut de <b>n</b> lignes.";
ACMsg.MICROBIT_IMAGE_SHIFT_DOWN = "Renvoie une nouvelle image décalée vers le bas de <b>n</b> lignes.";
ACMsg.MICROBIT_IMAGE_CROP = "Renvoie une nouvelle image recadrée depuis le rectangle en <b>x</b>, <b>y</b> de taille <b>w</b> x <b>h</b>.";
